    async def dismiss_cookie_dialog(self):
        for _ in range(20):
            clicked = await self.page.evaluate(
                """() => {
                    const cookieText =
                        /here.?s how we use cookies|how we use cookies/i;

                    const buttons = [
                        ...document.querySelectorAll(
                            "button, [role='button']"
                        )
                    ];

                    const isCookieClose = (element) => {
                        const label = (
                            element.innerText ||
                            element.textContent ||
                            element.getAttribute("aria-label") ||
                            ""
                        ).trim().toLowerCase();

                        if (label !== "close") {
                            return false;
                        }

                        let parent = element;

                        for (let i = 0; i < 10 && parent; i += 1) {
                            if (cookieText.test(parent.innerText || "")) {
                                return true;
                            }

                            parent = parent.parentElement;
                        }

                        return false;
                    };

                    const closeButton = buttons.find(isCookieClose);

                    if (!closeButton) {
                        return false;
                    }

                    closeButton.click();
                    return true;
                }"""
            )

            if clicked:
                await self.page.wait_for_timeout(1_000)
                return

            await self.page.wait_for_timeout(250)

        # Fallback when the cookie panel is keyboard-dismissible.
        await self.page.keyboard.press("Escape")
        await self.page.wait_for_timeout(500)


