    async def open_apply_leave_form(self):
        await self.dismiss_cookie_dialog()

        # Close the profile menu if it is open.
        await self.page.keyboard.press("Escape")
        await self.page.wait_for_timeout(500)

        pattern = re.compile(
            r"^\s*apply\s*(for\s*)?leave\s*$",
            re.IGNORECASE,
        )

        candidates = [
            self.page.get_by_role("button", name=pattern),
            self.page.get_by_role("link", name=pattern),
            self.page.get_by_text(pattern),
        ]

        target = None

        for locator in candidates:
            for index in range(await locator.count()):
                candidate = locator.nth(index)

                if await candidate.is_visible():
                    target = candidate
                    break

            if target is not None:
                break

        if target is None:
            buttons = await self.page.locator("button").all_inner_texts()
            links = await self.page.locator("a").all_inner_texts()

            raise AssertionError(
                "Apply Leave control was not found. "
                f"URL: {self.page.url}; "
                f"Buttons: {buttons}; Links: {links}"
            )

        clickable_parent = target.locator(
            "xpath=ancestor-or-self::*"
            "[self::button or self::a or @role='button'][1]"
        )

        if await clickable_parent.count():
            target = clickable_parent

        await target.scroll_into_view_if_needed()
        await target.click(force=True)

        for _ in range(20):
            body_text = (
                await self.page.locator("body").inner_text()
            ).lower()

            if re.search(
                r"leave\s*type|start\s*date|from\s*date|reason",
                body_text,
            ):
                return

            await self.page.wait_for_timeout(500)

        raise AssertionError(
            "Apply Leave was clicked, but the form did not open. "
            f"Current URL: {self.page.url}"
        )




    async def _find_visible(self, locators):
        for locator in locators:
            for index in range(await locator.count()):
                candidate = locator.nth(index)

                if await candidate.is_visible():
                    return candidate

        return None

