    async def fill_leave_type(self):
        leave_type = os.getenv("LMS_LEAVE_TYPE", "Casual")

        field_candidates = [
            self.page.get_by_role(
                "combobox",
                name=re.compile(
                    r"leave\s*type|type\s*of\s*leave",
                    re.IGNORECASE,
                ),
            ),
            self.page.get_by_label(
                re.compile(
                    r"leave\s*type|type\s*of\s*leave",
                    re.IGNORECASE,
                ),
            ),
            self.page.locator(
                "input[placeholder*='leave' i], "
                "input[name*='leave' i], "
                "[role='combobox']"
            ),
        ]

        leave_field = await self._find_visible(field_candidates)

        if leave_field is not None:
            tag_name = await leave_field.evaluate(
                "(element) => element.tagName.toLowerCase()"
            )

            if tag_name == "select":
                await leave_field.select_option(label=leave_type)
                return

            await leave_field.click(force=True)

        else:
            leave_type_text = self.page.get_by_text(
                re.compile(
                    r"leave\s*type|type\s*of\s*leave",
                    re.IGNORECASE,
                )
            ).first

            await expect(leave_type_text).to_be_visible(
                timeout=15_000
            )

            await leave_type_text.click(force=True)

        await self.page.wait_for_timeout(300)

        option = self.page.get_by_text(
            re.compile(
                rf"^{re.escape(leave_type)}$",
                re.IGNORECASE,
            )
        ).last

        await expect(option).to_be_visible(timeout=15_000)
        await option.click(force=True)


