    async def fill_dates(self):
        start_date = os.getenv(
            "LMS_LEAVE_START_DATE",
            "2026-09-22",
        )

        end_date = os.getenv(
            "LMS_LEAVE_END_DATE",
            start_date,
        )

        # Use only fields belonging to the currently opened leave form.
        form = self.page.locator(
            "form:visible, "
            "[role='dialog']:visible, "
            "section:visible"
        ).last

        if await form.count() == 0:
            form = self.page.locator("body")

        # First preference: native date inputs.
        date_fields = form.locator(
            "input[type='date']:visible"
        )

        visible_date_fields = []

        for index in range(await date_fields.count()):
            field = date_fields.nth(index)

            if await field.is_visible():
                visible_date_fields.append(field)

        # Second preference: text inputs associated with date labels.
        if len(visible_date_fields) < 2:
            labelled_fields = form.locator(
                "input:visible"
            )

            for index in range(await labelled_fields.count()):
                field = labelled_fields.nth(index)

                field_type = (
                    await field.get_attribute("type") or ""
                ).lower()

                name = (
                    await field.get_attribute("name") or ""
                ).lower()

                field_id = (
                    await field.get_attribute("id") or ""
                ).lower()

                placeholder = (
                    await field.get_attribute("placeholder") or ""
                ).lower()

                descriptor = " ".join(
                    [name, field_id, placeholder]
                )

                if (
                    field_type != "hidden"
                    and (
                        "date" in descriptor
                        or "from" in descriptor
                        or "to" in descriptor
                        or "start" in descriptor
                        or "end" in descriptor
                    )
                ):
                    if field not in visible_date_fields:
                        visible_date_fields.append(field)

        if len(visible_date_fields) < 2:
            inputs = await form.locator(
                "input:visible"
            ).count()

            raise AssertionError(
                "Could not find two date fields in the open "
                f"Apply Leave form. Visible inputs found: {inputs}"
            )

        start_field = visible_date_fields[0]
        end_field = visible_date_fields[1]

        await self._enter_date_without_calendar(
            start_field,
            start_date,
        )

        await self._enter_date_without_calendar(
            end_field,
            end_date,
        )

        await self.page.wait_for_timeout(500)

    async def _enter_date_without_calendar(
        self,
        field,
        iso_value,
    ):
        await field.scroll_into_view_if_needed()

        field_type = (
            await field.get_attribute("type") or "text"
        ).lower()

        if field_type == "date":
            value = iso_value
        else:
            value = date.fromisoformat(
                iso_value
            ).strftime("%m/%d/%Y")

        # Prevent the native calendar popup from being opened.
        await field.focus()

        try:
            await field.fill(value, timeout=3_000)
        except Exception:
            await field.evaluate(
                """(element, value) => {
                    const setter =
                        Object.getOwnPropertyDescriptor(
                            HTMLInputElement.prototype,
                            "value"
                        ).set;

                    if (setter) {
                        setter.call(element, value);
                    } else {
                        element.value = value;
                    }

                    element.dispatchEvent(
                        new Event("input", { bubbles: true })
                    );

                    element.dispatchEvent(
                        new Event("change", { bubbles: true })
                    );

                    element.dispatchEvent(
                        new Event("blur", { bubbles: true })
                    );
                }""",
                value,
            )

        await field.press("Tab")





    async def fill_reason(self):
        reason = os.getenv(
            "LMS_LEAVE_REASON",
            "Personal leave requested for testing.",
        )

        reason_field = await self._find_visible(
            [
                self.page.get_by_label(
                    re.compile(
                        r"reason|remarks|comments",
                        re.IGNORECASE,
                    )
                ),
                self.page.locator("textarea").first,
            ]
        )

        if reason_field is not None:
            await reason_field.fill(reason)

    async def submit_leave(self):
        submit_button = await self._find_visible(
            [
                self.page.get_by_role(
                    "button",
                    name=re.compile(
                        r"submit|apply leave|request leave",
                        re.IGNORECASE,
                    ),
                ),
                self.page.locator(
                    "button[type='submit'], input[type='submit']"
                ),
            ]
        )

        if submit_button is None:
            raise AssertionError("Leave submit button was not found.")

        await submit_button.scroll_into_view_if_needed()
        await submit_button.click(force=True)

    async def validate_leave_applied(self):
        success_message = self.page.get_by_text(
            re.compile(
                r"leave.*(applied|submitted|success)"
                r"|successfully.*leave",
                re.IGNORECASE,
            )
        )

        try:
            await expect(success_message.first).to_be_visible(
                timeout=15_000
            )
            print("Leave was applied successfully.")
            return
        except PlaywrightTimeoutError:
            pass

        upcoming_leaves = self.page.get_by_role(
            "heading",
            name=re.compile(
                r"my upcoming leaves",
                re.IGNORECASE,
            ),
        )

        await expect(upcoming_leaves.first).to_be_visible(
            timeout=15_000
        )

        print("Leave was applied successfully.")
